// densifica e deixa a mão levemente trêmula
function _cadPreparar(pts, esc, r, fase) {
  const out = []; for (let i = 0; i < pts.length; i++) { out.push(pts[i]); if (i < pts.length - 1) { const a = pts[i], b = pts[i + 1], l = Math.hypot(b[0] - a[0], b[1] - a[1]), n = Math.floor(l * esc / 14); for (let k = 1; k <= n; k++) out.push([a[0] + (b[0] - a[0]) * k / (n + 1), a[1] + (b[1] - a[1]) * k / (n + 1)]); } }
  return out.map(([x, y]) => [x + Math.sin(y * 0.09 * esc + fase) * 1.1 / esc, y + Math.cos(x * 0.08 * esc + fase * 1.7) * 1.1 / esc]);
}
function _cadHachura(poly, ang, sp) {
  const a = (ang * Math.PI) / 180, ux = Math.cos(a), uy = Math.sin(a), nx = -uy, ny = ux, n = poly.length; let mn = 1e9, mx = -1e9;
  for (const p of poly) { const d = p[0] * nx + p[1] * ny; mn = Math.min(mn, d); mx = Math.max(mx, d); }
  const segs = []; for (let d = mn + sp / 2; d < mx; d += sp) { const xs = [];
    for (let i = 0; i < n; i++) { const p = poly[i], q = poly[(i + 1) % n], dp = p[0] * nx + p[1] * ny - d, dq = q[0] * nx + q[1] * ny - d; if ((dp < 0) !== (dq < 0)) { const t = dp / (dp - dq); xs.push((p[0] + (q[0] - p[0]) * t) * ux + (p[1] + (q[1] - p[1]) * t) * uy); } }
    xs.sort((u, v) => u - v); for (let k = 0; k + 1 < xs.length; k += 2) { const s0 = xs[k] + 2, s1 = xs[k + 1] - 2; if (s1 > s0) segs.push([[d * nx + s0 * ux, d * ny + s0 * uy], [d * nx + s1 * ux, d * ny + s1 * uy]]); } }
  return segs;
}
// desenha uma lista de traços locais { t, h } na página
function cadTracos(pg, def, o = {}) {
  const esc = o.esc ?? 1, r = prng(Math.round((o.seed ?? 1) * 733 + (o.x || 0) * 3 + (o.y || 0))), fase = r() * 6.28, rot = ((o.rot || 0) * Math.PI) / 180, cr = Math.cos(rot), sr = Math.sin(rot), fx = o.espelho ? -1 : 1;
  const T = ([x, y]) => { x *= fx * esc; y *= esc; return [o.x + x * cr - y * sr, o.y + x * sr + y * cr]; };
  const cont = def.t.map((p) => _cadPreparar(p, esc, r, fase).map(T));
  const hs = []; for (const h of def.h || []) { const poly = h.poly.map(T); for (const s of _cadHachura(poly, h.ang + (o.rot || 0), h.sp * Math.max(esc, 0.6))) hs.push({ s, cor: h.cor }); }
  const ts = o.ts, te = o.te, dc = (te - ts) * (hs.length ? 0.68 : 1), w = o.w ?? Math.max(3.2, 4.4 * Math.max(esc, 0.7));
  const ag = _cadAgenda(cont, ts, ts + dc, 14);
  const pai = o.pai || pg.gDes, tr = cont.map((p, i) => _cadTraco(pg, p, { cor: o.cor || CAD_TINTA, w, ts: ag[i][0], te: ag[i][1], pai, caneta: false }));
  const ht = [];
  if (hs.length) { const ah = _cadAgenda(hs.map((q) => q.s), ts + dc, te, 4); const base = pai.firstChild;
    hs.forEach((q, i) => { const a = q.s[0], b = q.s[1], t = _cadTraco(pg, [[a[0] - r() * 2, a[1] - r() * 2], [b[0] + r() * 2, b[1] + r() * 2]], { cor: q.cor, w: Math.max(5, 7.5 * Math.max(esc, 0.7)), ts: ah[i][0], te: ah[i][1], op: 0.5, pai, caneta: false });
      if (base && base.parentNode === pai) pai.insertBefore(t.el, base); ht.push(t); }); }
  const item = { ts, te, tracos: [...tr, ...ht], tipo: "desenho" }; if (o.com && o.com.item) item.apagaCom = o.com.item.apagaCom; pg.itens.push(item); return item;
}
function cadDesenho(pg, nome, o = {}) { return cadTracos(pg, CAD_DES[nome](), o); }
// anotações: sublinhado ondulado, círculo em volta de uma palavra, seta curva
function cadSublinhado(pg, x0, x1, y, ts, te, o = {}) { const r = prng(Math.round(x0 + y)), p = []; for (let i = 0; i <= 12; i++) p.push([x0 + (x1 - x0) * i / 12, y + Math.sin(i * 1.3) * 3 + (r() - 0.5) * 2]);
  const q = []; for (let i = 0; i <= 12; i++) q.push([x0 + 10 + (x1 - x0 - 14) * i / 12, y + 9 + Math.sin(i * 1.1 + 1) * 3]);
  return cadTracos(pg, { t: o.duplo === false ? [p] : [p, q] }, { x: 0, y: 0, ts, te, cor: o.cor || CAD_VERM, w: o.w ?? 4.4, com: o.com }); }
function cadCirculo(pg, cx, cy, rx, ry, ts, te, o = {}) { const p = []; for (let i = 0; i <= 44; i++) { const a = (-0.5 + (i / 44) * 6.9), k = 1 + 0.06 * (i / 44); p.push([cx + Math.cos(a) * rx * k, cy + Math.sin(a) * ry * k]); }
  return cadTracos(pg, { t: [p] }, { x: 0, y: 0, ts, te, cor: o.cor || CAD_VERM, w: o.w ?? 4.6, com: o.com }); }

// ============================== uma caneta só ==============================
// A mão escreve uma coisa de cada vez: palavras e rabiscos entram numa fila (na ordem em que o roteiro os pede) e a caneta
// vai de um ao outro. Cada coisa começa na hora pedida (a palavra, quando é dita) ou, se a mão ainda estiver ocupada, logo
// que ela se livra; escreve um pouco mais devagar que a fala (calma) e, se ficar para trás, escreve mais depressa para alcançar.
function cadFechar(pg, o = {}) {
  pg.fechada = true; const lento = o.lento ?? 1.0, lentoD = o.lentoDes ?? 1.1; let cur = 0;
  // rabiscos (tipo "desenho") aparecem na hora pedida, ao mesmo tempo que a caneta escreve as palavras, sem caneta própria e sem entrar na fila
  const L = pg.itens.filter((it) => it.tipo === "texto").map((it, i) => [it, i]).sort((a, b) => a[0].ts - b[0].ts || a[1] - b[1]).map((q) => q[0]);
  for (const it of L) {
    const d = Math.max(0.05, it.te - it.ts), ini = Math.max(it.ts, cur), atraso = ini - it.ts;
    let dur = it.tipo === "texto" ? Math.max(0.36, d * lento) : d * lentoD;
    // atrasou: escreve mais depressa para terminar quando a palavra terminaria (alcança a fala em vez de arrastar o atraso)
    if (atraso > 0.05) dur = Math.max(0.14 + (it.w || 200) / 2600, Math.min(dur, it.te - ini));
    const k = dur / d;
    for (const s of it.tracos) { const a = s.ts - it.ts, b = s.te - it.ts; s.ts = ini + a * k; s.te = ini + b * k; }
    it.ts = ini; it.te = ini + dur; cur = it.te + 0.03;
  }
  for (const it of pg.itens) if (it.apagaCom) for (const s of it.tracos) s.ap = it.apagaCom.ts - 0.2;
}

// ============================== atalhos de cena ==============================
const cadAjusta = (txt, fonte, larg, max) => Math.min(max, larg / cadMede(txt, fonte, 1));
const cadZoom = (pg, c, z = 1.035) => tl.fromTo(pg.raiz, { scale: 1, svgOrigin: "540 960" }, { scale: z, svgOrigin: "540 960", duration: c.fim - c.ini + 0.5, ease: "none", immediateRender: false }, c.ini);
// título/gancho em linhas centralizadas: linhas = [{ txt, fonte, max, cor, marca }]; devolve o instante final
function cadTitulo(pg, linhas, y, ts, dur, o = {}) {
  let t = ts; const por = dur / linhas.length, passo = o.passo || 150;
  linhas.forEach((l, i) => { const f = l.fonte || "elfin", e = cadAjusta(l.txt, f, o.larg || 880, l.max || 0.2), yy = y + i * passo;
    const r = cadTexto(pg, l.txt, { x: 540, y: yy, esc: e, fonte: f, cor: l.cor || CAD_TINTA, ts: t, te: t + por * 0.92, alinhar: "centro", seed: 40 + i, w: Math.max(5, e * 42) });
    if (l.marca) r.tracos.push(cadMarca(pg, r.x0, r.x1, yy - e * 150, t, t + 0.3, { esp: e * 330 }));
    t += por; });
  return t;
}

// brasas/faíscas que sobem de um ponto (fogueira): pontinhos de luz que nascem, sobem tremendo e apagam (determinístico)
function cadFaiscas(pg, x, y, ts, te, o = {}) {
  const n = o.n ?? 14, r = prng(Math.round(x * 7 + y)), g = _cadEl(o.pai || pg.gDes, "g", {}), P = [];
  for (let k = 0; k < n; k++) P.push({ el: _cadEl(g, "circle", { r: (2 + r() * 3.5).toFixed(1), fill: k % 3 ? "#f29a2e" : "#ffd36b", opacity: 0 }), f: r(), v: 70 + r() * 90, a: 10 + r() * 22, w: 1 + r() * 2, h: (o.alt ?? 230) * (0.6 + r() * 0.5) });
  _CAD.extras.push((t) => { for (const q of P) { if (t < ts || t > te + 2) { q.el.setAttribute("opacity", 0); continue; }
    const u = ((t - ts) * q.v / q.h + q.f) % 1, ent = Math.min(1, (t - ts) / 0.6) * Math.max(0, Math.min(1, (te + 2 - t) / 0.8));
    q.el.setAttribute("cx", (x + Math.sin((t + q.f * 9) * q.w) * q.a * u).toFixed(1)); q.el.setAttribute("cy", (y - u * q.h).toFixed(1));
    q.el.setAttribute("opacity", (ent * Math.sin(Math.PI * u) * 0.95).toFixed(2)); } });
  return g;
}
